for ids in [[],[1],[1,2,3],[2,4,6]]:
 for cursor in [-1,0,1,2,3,6,7]:
  for limit in [1,2,4]: rows.append([[ids,cursor,limit],page(ids,cursor,limit),[i for i in ids if i>cursor][:limit]])
